pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        c.NETM();

        vm.prank(caller);
        c.getTokens();

        // In the reference, after first getTokens(), value is reduced so subsequent call returns 0 value.
        // When value is 0, the transfer amount is 0 and blacklist[caller] stays false.
        // In the mutant, value never decreases, so getTokens() will transfer >0 and blacklist[caller] becomes true.
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}("");
        require(success);

        // After second getTokens(), if the caller was not blacklisted after the first call,
        // then blacklist[caller] should still be false in reference (value=0), but mutant will have true.
        // We check blacklist[caller] after the second call:
        assertTrue(!c.blacklist(caller));
    }
}

