pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));

        // Setup: call NETM() to initialize balances
        vm.prank(caller);
        c.NETM();

        // Record initial value
        uint256 valueBefore = c.value();

        // Call getTokens() once
        vm.prank(caller);
        c.getTokens();

        // Get new value
        uint256 valueAfter = c.value();

        // The value should decrease (unless value was already 0)
        assertTrue(valueAfter <= valueBefore, "Value should not increase after getTokens()");

        // Additional check: value should have decreased by at least 1 if it was > 0
        if (valueBefore > 0) {
            assertTrue(valueAfter < valueBefore || valueAfter == 0, "Value should decrease when positive");
        }
    }
}

