pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _to, uint256 _amount) public {
        // Bound _amount to avoid overflow, but ensure it can sum to totalDistributed >= totalSupply
        vm.assume(_to != address(0));
        vm.assume(_amount > 0 && _amount <= 250000000e18);
        // We need to run NETM() which sets owner = msg.sender and gives them totalDistributed
        // But to trigger the distribution finish, we need to distribute enough via the public getTokens path
        // Since NETM() just sets balances, we will simulate distribution by calling getTokens repeatedly
        // However, getTokens requires distributionFinished == false and blacklist[msg.sender] == false
        // We'll use deal to give some ETH to call getTokens, then call NETM() at the end

        // First, ensure contract has enough remaining for distribution
        // We'll call getTokens multiple times with enough value to exhaust totalRemaining
        uint256 totalToDistribute = 250000000e18; // initial totalRemaining
        while (c.totalRemaining() > 0) {
            // Fund the caller
            vm.deal(address(this), 1 ether);
            // Call getTokens (this will use value which decreases each time)
            // But since we cannot control msg.value in fuzz easily, we'll use a simpler approach:
            // Use NETM() which sets distributionFinished based on totalDistributed >= totalSupply
            // Actually, NETM() just sets balances[owner] = totalDistributed, it doesn't call distr
            // So distributionFinished remains false initially.
            // The only way to set distributionFinished true is through distr or finishDistribution.
            // Since distr is private, we need to trigger it via getTokens.
            break;
        }

        // Simpler approach: call NETM() and then check if totalDistributed >= totalSupply
        c.NETM();
        // After NETM(), totalDistributed = 250000000e18, totalSupply = 500000000e18
        // So totalDistributed < totalSupply, distributionFinished remains false in both versions
        // To make it true, we need to call getTokens to distribute more
        // But getTokens requires whitelist (not blacklisted)
        // Let's use vm.deal to give some ETH and call getTokens
        vm.deal(address(this), 1 ether);
        // We'll call getTokens with a value that will eventually exhaust totalRemaining
        // Since value decreases each time, we need many calls
        // For test simplicity, we can just assert a general rule about the bug:
        // In the buggy version, distributionFinished never becomes true via distr
        // So we can check: after enough distribution, distributionFinished should be true

        // Simulate distribution by calling getTokens many times
        for (uint256 i = 0; i < 100; i++) {
            try c.getTokens() {
                // success
            } catch {
                break;
            }
        }

        // Now assert: if totalDistributed >= totalSupply, then distributionFinished must be true
        bool condition = c.totalDistributed() >= c.totalSupply();
        assertTrue(!condition || c.distributionFinished());
    }
