        // Reference: if call succeeds, ownerAfter == sender
        // Buggy: if call succeeds, ownerAfter != sender (except by chance if original owner == sender)
        // So rule: when sender != original owner, a successful call must change owner to sender

        assertTrue(!success || ownerAfter == sender);
    }
}

