pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 callAmount) public {
        vm.assume(caller != address(0));
        uint256 initialValue = c.value();
        uint256 initialTotalRemaining = c.totalRemaining();

        // Call NETM() which sets owner's balance
        c.NETM();

        // Now call getTokens() through the fallback with enough value
        // The value variable should be capped to totalRemaining if exceeded
        vm.deal(address(c), 1 ether);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: callAmount}("");

        uint256 finalValue = c.value();
        uint256 finalTotalRemaining = c.totalRemaining();

        // The rule: after the getTokens() call, value should be <= totalRemaining
        // and if success, the value transferred should equal the amount distributed
        // (which is the min of original value and totalRemaining before the call)
        if (success) {
            uint256 toGive = initialValue;
            if (initialValue > initialTotalRemaining) {
                toGive = initialTotalRemaining;
            }
            // The value after the call should be (toGive / 100000) * 99999
            uint256 expectedNewValue = (toGive / 100000) * 99999;
            assertTrue(finalValue == expectedNewValue, "Value not correctly updated after distribution");
        }
        assertTrue(finalValue <= finalTotalRemaining, "Value exceeds totalRemaining after getTokens");
    }
}

