pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, address caller) public {
        // Bound seed to a reasonable range for value changes
        uint256 iterations = bound(seed, 0, 10);
        vm.assume(caller != address(0));

        // Record initial value
        uint256 initialValue = c.value();

        // Simulate multiple getTokens calls
        uint256 currentValue = initialValue;
        for (uint256 i = 0; i < iterations; i++) {
            // Provide enough ether if needed (getTokens is payable but doesn't require ether)
            vm.deal(caller, 1 ether);
            vm.prank(caller);
            c.getTokens();

            // After each call, value should be non-increasing
            uint256 newValue = c.value();
            assertTrue(newValue <= currentValue, "value should not increase after getTokens");
            currentValue = newValue;
        }

        // Final check: after all iterations, value is <= initial value
        assertTrue(c.value() <= initialValue, "value should be non-increasing overall");
    }
}

